	{
		FRHIResourceCreateInfo CreateInfo(TEXT("FLoyCustomMeshIndexBuffer"));
		IndexBufferRHI = RHICreateIndexBuffer(sizeof(int32), NumIndices * sizeof(int32), BUF_Dynamic, CreateInfo);
	}

